CREATE OR REPLACE FUNCTION sp_getallproducts()
RETURNS TABLE (
    productid INT, name VARCHAR(100), description VARCHAR(500),
    price NUMERIC(18, 2), stockquantity INT, createddate TIMESTAMP, modifieddate TIMESTAMP
) AS $$
BEGIN
    RETURN QUERY
    SELECT p.productid, p.name, p.description, p.price, p.stockquantity, p.createddate, p.modifieddate
    FROM products p ORDER BY p.name;
END;
$$ LANGUAGE plpgsql;

